{"cards": [{"node_code": "N_6efddb562945a179", "definition": "支撑航海实践的基础理论学科，涵盖天文学、数学、气象、潮汐及电子学在航海中的应用，以及航海历书等基础数据资源。", "boundary": "本节点聚焦于航海所需的“基础科学原理”与“理论数据”。边界在于区分“应用操作”（如具体的航位测定方法、船舶操纵动作）和“仪器硬件”（如雷达、GPS的物理构造）。若内容涉及利用天文原理计算位置，归入本节点；若涉及具体仪器操作，归入航行仪器或航位测定。", "includes": ["航海天文学、航海数学及航海历书数据", "航海气象学、潮汐学及其对航行的影响分析", "航海电子学基础理论及信号处理原理"], "excludes": ["具体导航仪器的硬件制造与机械结构（归入船舶工程或相关仪器节点）", "具体的船舶操纵动作与避让战术（归入船舶操纵技术）"], "sibling_distinctions": [{"other_code": "N_0a2153b9eed35ee9", "rule": "本节点提供定位所需的科学原理（如天文观测原理），兄弟节点关注利用这些原理进行具体位置计算与确定的操作流程。"}, {"other_code": "N_d4995ceafb64dfca", "rule": "本节点关注仪器背后的科学原理（如电磁波传播），兄弟节点关注仪器本身的功能、使用规范及维护。"}], "cross_boundary_rule": "若内容涉及导航算法的数学推导，主挂载本节点；若涉及算法在特定硬件上的实现与调试，需视具体侧重，通常偏向仪器或导航系统。"}, {"node_code": "N_d4995ceafb64dfca", "definition": "船舶驾驶台及航行过程中使用的各类仪器、设备、工具及其使用规范、维护保养与性能测试。", "boundary": "本节点聚焦于“工具”本身及其在航海中的“应用”。边界在于区分“科学原理”（归入航海基础科学）和“系统通信”（归入船舶导航与通信）。若内容涉及罗经、雷达、测深仪等单台仪器的操作、校准与故障排除，归入本节点；若涉及多设备集成的综合导航系统架构，归入船舶导航与通信。", "includes": ["罗经、雷达、回声测深仪、计程仪等航行仪器的原理与使用", "航行日志、海图作业工具及驾驶台设备配置", "航行仪器的日常维护、校准及性能检验标准"], "excludes": ["导航仪器的底层电子电路设计与芯片研发（归入航海电子学或船舶工程）", "船舶通信电台、卫星通信系统的组网与协议（归入船舶导航与通信）"], "sibling_distinctions": [{"other_code": "N_253238d4186203d2", "rule": "本节点侧重单台或独立航行仪器的操作与维护，兄弟节点侧重导航与通信系统的集成、数据链及通信协议。"}, {"other_code": "N_6efddb562945a179", "rule": "本节点关注仪器的“怎么用”和“怎么修”，兄弟节点关注仪器背后的“为什么”（科学原理）。"}], "cross_boundary_rule": "若内容涉及AIS（自动识别系统）的操作与显示，主挂载本节点；若涉及AIS的数据传输协议及与岸基系统的通信交互，主挂载船舶导航与通信。"}, {"node_code": "N_949428e54db9946d", "definition": "船舶在航行中用于视觉、听觉及灯光信号传递的规则、标准、设备及其在避碰与通信中的应用。", "boundary": "本节点聚焦于“信号”作为信息载体的规范与使用。边界在于区分“通信系统”（归入船舶导航与通信）和“操纵动作”（归入船舶操纵技术）。若内容涉及《国际海上避碰规则》中的号灯、号型、声号规定，归入本节点；若涉及VHF语音通信或GMDSS系统，归入船舶导航与通信。", "includes": ["国际及国内航行信号规则（号灯、号型、声号）", "信号旗、灯光信号及声号设备的使用规范", "信号在船舶避碰、进出港及应急情况下的应用"], "excludes": ["无线电通信、卫星通信及数据链传输技术（归入船舶导航与通信）", "船舶操纵的具体战术动作与轨迹控制（归入船舶操纵技术）"], "sibling_distinctions": [{"other_code": "N_253238d4186203d2", "rule": "本节点关注非无线电的视觉/听觉信号及避碰规则中的信号规定，兄弟节点关注无线电、卫星等电子通信手段及系统。"}, {"other_code": "N_4c709dbaf9b22849", "rule": "本节点关注“发什么信号”（规则与设备），兄弟节点关注“怎么动船”（操纵手法与战术）。"}], "cross_boundary_rule": "若内容涉及VHF通话中的标准用语，主挂载船舶导航与通信；若涉及VHF通话中配合避碰规则发出的特定信号含义，可关联本节点，但主挂载通常依据通信手段归入通信节点，除非侧重规则解读。"}]}
